require("src/utils/List")
local JQRichTextUtils = require("src/ui/components/reach/richtext/JQRichTextUtils")
local JQRichTextConstants = require("src/ui/components/reach/richtext/JQRichTextConstants")
local JQRichTextFormatModel = require("src/ui/components/reach/richtext/data/JQRichTextFormatModel")
local JQRichTextSerialization = class("JQRichTextSerialization")

function JQRichTextSerialization:ctor()
    self:initData()
end

function JQRichTextSerialization:initData()
    self.groups = List({})
    self.defaultFormat = nil
end

function JQRichTextSerialization:reset()
    self.groups = List({})
end

function JQRichTextSerialization:serialize(formats, defaultFormat)
    self.defaultFormat = defaultFormat or JQRichTextFormatModel.new()
    self:reset()
    self:grouping(formats)
    self:merge()
    self:filter()
    local text = self:packet()
    if text == "" then
        text = JQRichTextConstants.DEFAULT_TEXT
    end
    return text
end

function JQRichTextSerialization:grouping(formats)
    local lastGroupIndex = -1
    table.foreach(clone(formats), function(_, format)
        if format.groupIndex ~= lastGroupIndex then
            table.insert(self.groups, {})
        end
        table.insert(self.groups:tail(), format)
        lastGroupIndex = format.groupIndex
    end)
end

function JQRichTextSerialization:merge()
    for _, group in ipairs(self.groups) do
        for i = #group, 2, -1 do
            if JQRichTextUtils:isFormatSimilar(group[i], group[i - 1]) then
                JQRichTextUtils:mergeFormat(group[i - 1], group[i])
                table.remove(group, i)
            end
        end
    end
end

function JQRichTextSerialization:filter()
    for _, group in ipairs(self.groups) do
        for i = #group, 1, -1 do
            local element = group[i]
            if element.type == JQRichTextConstants.TYPES.TEXT then
                if element.text == "" and #group > 1 then
                    table.remove(group, i)
                end
            end
        end
    end
end

function JQRichTextSerialization:packet()
    local elements = {}
    for _, group in ipairs(self.groups) do
        table.insert(elements, self:packetGroupAlignStart(group[1]))
        for _, element in ipairs(group) do
            if element.type == JQRichTextConstants.TYPES.IMAGE then
                table.insert(elements, self:packetImage(element))
            else
                table.insert(elements, self:packetText(element))
            end
        end
        table.insert(elements, self:packetGroupAlignEnd(group[1]))
    end
    return table.concat(elements)
end

function JQRichTextSerialization:packetGroupAlignStart(section)
    local ret = {"<", JQRichTextConstants.HTML.TAG_DIV}

    local hasAlign = self:hasGroupAlign(section)
    if hasAlign then
        table.insertto(ret, {" ", JQRichTextConstants.HTML.ATTRIBUTE_ALIGN, "=", section.groupAlign})
    end

    table.insert(ret, ">")

    return table.concat(ret)
end

function JQRichTextSerialization:packetGroupAlignEnd()
    local ret = {"</", JQRichTextConstants.HTML.TAG_DIV, ">"}
    return table.concat(ret)
end

function JQRichTextSerialization:packetText(element)
    local ret = {"<", JQRichTextConstants.HTML.TAG_TEXT, ">", "</", JQRichTextConstants.HTML.TAG_TEXT, ">"}
    local hasColor = self:hasColor(element)
    local hasFontSize = self:hasFontSize(element)
    local hasFontName = self:hasFontName(element)
    local hasBold = element.bold
    local hasUnderline = checknumber(element.underlineWidth) ~= 0 and true or false
    local hasLineHeight = self:hasLineHeight(element)
    local hasBgColor = element.hasBgColor
    local hasisReviseInsert = element.isReviseInsert
    local text = element.text .. (element.tailWithLF and "\n" or "")

    if hasColor then
        table.insert(ret, 3, self:getSerializedAttribute(element, JQRichTextConstants.HTML.FORMAT_COLOR))
    end
    if hasFontName then
        table.insert(ret, 3, self:getSerializedAttribute(element, JQRichTextConstants.HTML.FORMAT_FONT_NAME))
    end
    if hasFontSize then
        table.insert(ret, 3, self:getSerializedAttribute(element, JQRichTextConstants.HTML.FORMAT_FONT_SIZE))
    end
    if hasBgColor then
        table.insert(ret, 3, self:getSerializedAttribute(element, JQRichTextConstants.HTML.FORMAT_BG_COLOR))
    end
    if hasUnderline then
        table.insert(ret, 3, self:getSerializedAttribute(element, JQRichTextConstants.HTML.FORMAT_UNDERLINE))
    end
    if hasLineHeight then
        table.insert(ret, 3, self:getSerializedAttribute(element, JQRichTextConstants.HTML.FORMAT_LINE_HEIGHT))
    end

    if hasBold then
        table.insert(ret, #ret - 2, "<b>")
    end
    if hasisReviseInsert then
        local opStr = self:applyParameter("", JQRichTextConstants.HTML.OPTS_INSET, hasisReviseInsert)
        table.insert(ret, #ret - 2, "<op" .. opStr .. ">")
    end

    table.insert(ret, #ret - 2, string.htmlspecialchars(text))

    if hasisReviseInsert then
        table.insert(ret, #ret - 2, "</op>")
    end
    if hasBold then
        table.insert(ret, #ret - 2, "</b>")
    end

    return table.concat(ret)
end

function JQRichTextSerialization:applyParameter(str, key, val)
    if val ~= nil and val ~= false then
        if type(val) == "boolean" then
            val = ternary(val, 1, 0)
        end
        local dataStr = key .. "=" .. val
        str = str .. " " .. dataStr
    end

    return str
end

function JQRichTextSerialization:packetImage()
    return ""
end

function JQRichTextSerialization:getSerializedAttribute(section, formatName)
    local attributeName
    local formatValue = section[formatName]
    if formatName == JQRichTextConstants.HTML.FORMAT_COLOR then
        attributeName = JQRichTextConstants.HTML.ATTRIBUTE_COLOR
        formatValue = JQRichTextUtils:toHexColor(formatValue)
    elseif formatName == JQRichTextConstants.HTML.FORMAT_FONT_NAME then
        attributeName = JQRichTextConstants.HTML.ATTRIBUTE_FONT_NAME
    elseif formatName == JQRichTextConstants.HTML.FORMAT_FONT_SIZE then
        attributeName = JQRichTextConstants.HTML.ATTRIBUTE_FONT_SIZE
    elseif formatName == JQRichTextConstants.HTML.FORMAT_BG_COLOR then
        attributeName = JQRichTextConstants.HTML.ATTRIBUTE_BG_COLOR
        formatValue = JQRichTextUtils:toHexColor(formatValue)
    elseif formatName == JQRichTextConstants.HTML.FORMAT_UNDERLINE then
        attributeName = JQRichTextConstants.HTML.ATTRIBUTE_UNDERLINE
    elseif formatName == JQRichTextConstants.HTML.FORMAT_LINE_HEIGHT then
        attributeName = JQRichTextConstants.HTML.ATTRIBUTE_LINE_HEIGHT
    end
    if attributeName then
        return table.concat({" ", attributeName, "=", formatValue})
    end
    return ""
end

function JQRichTextSerialization:hasFontSize(section)
    local fontSize = checknumber(section.fontSize)
    return fontSize > 0 and section.fontSize ~= self.defaultFormat.fontSize
end

function JQRichTextSerialization:hasFontName(section)
    if not section.fontName then
        return false
    end
    return section.fontName ~= self.defaultFormat.fontName
end

function JQRichTextSerialization:hasColor(section)
    if not section.color then
        return false
    end
    return not JQRichTextUtils:isColorEqual(section.color, self.defaultFormat.color)
end

function JQRichTextSerialization:hasLineHeight(section)
    if checknumber(section.lineHeight) <= 0 then
        return false
    end
    return section.lineHeight ~= self.defaultFormat.lineHeight
end

function JQRichTextSerialization:hasGroupAlign(section)
    if not section.groupAlign then
        return false
    end
    return section.groupAlign ~= self.defaultFormat.groupAlign
end

local serialization = JQRichTextSerialization.new()
return serialization
